cd /work; cat > /tmp/conv.pl <<'EOF'
undef $/; $_=<STDIN>;
# A
s/lemma A \(n:ℕ\+\) : ∀ \(k:ℕ\)/have A : ∀ (n:ℕ+), ∀ (k:ℕ)/; s/(have A .*?:= by
)  intro k/$1  intro n k/s;
s/lemma W \{ι : Type\} \[Fintype ι\] \[DecidableEq ι\] \(k : ℕ\) \(g : Fin k → ι\) \(hg : Function.Surjective g\) :/have W : ∀ {ι : Type} [Fintype ι] [DecidableEq ι] (k : ℕ) (g : Fin k → ι) (hg : Function.Surjective g),/;
s/(have W .*?:= by
)/$1  intro ι _ _ k g hg
/s;
s/lemma Rl \(n k : ℕ\+\) \(f : Fin k → Fin \(2\*n\)\) \(g : Fin k → Fin n\) \(b : Fin k → Bool\)
    \(hR : (.*?)\) \(i : Fin n\) :/have Rl : ∀ (n k : ℕ+) (f : Fin k → Fin (2*n)) (g : Fin k → Fin n) (b : Fin k → Bool)
    (hR : $1) (i : Fin n),/s;
s/(have Rl .*?:= by
)/$1  intro n k f g b hR i
/s;
s/lemma memEq \(n k : ℕ\+\) \(f : Fin k → Fin \(2\*n\)\) \(g : Fin k → Fin n\) \(b : Fin k → Bool\)
    \(hR : (.*?)\) :
/have memEq : ∀ (n k : ℕ+) (f : Fin k → Fin (2*n)) (g : Fin k → Fin n) (b : Fin k → Bool)
    (hR : $1),
/s;
s/(have memEq .*?:= by
)/$1  intro n k f g b hR
/s;
s/lemma Bc \(n : ℕ\+\) \(k : ℕ\) \(f : Fin k → Fin \(2\*n\)\) :/have Bc : ∀ (n : ℕ+) (k : ℕ) (f : Fin k → Fin (2*n)),/;
s/(have Bc .*?:= by
)/$1  intro n k f
/s;
s/lemma Cc \(n : ℕ\+\) \(k : ℕ\) \(g : Fin k → Fin n\) \(i : Fin \(2\*n\)\) :/have Cc : ∀ (n : ℕ+) (k : ℕ) (g : Fin k → Fin n) (i : Fin (2*n)),/;
s/(have Cc .*?:= by
)/$1  intro n k g i
/s;
s/lemma Ex \(n k : ℕ\+\) \(m : ℕ\) \(hk : \(k:ℕ\) = n \+ \(m\+m\)\) :/have Ex : ∀ (n k : ℕ+) (m : ℕ) (hk : (k:ℕ) = n + (m+m)),/;
s/(have Ex .*?:= by
)/$1  intro n k m hk
/s;
s/lemma mainN \(n k : ℕ\+\) \(hk : \(n:ℕ\) ≤ k\) \(hex : (.*?)\) :
/have mainN : ∀ (n k : ℕ+) (hk : (n:ℕ) ≤ k) (hex : $1),
/s;
s/(have mainN .*?:= by
)/$1  intro n k hk hex
/s;
print;
EOF
for f in t1 t2 t3 t3b t4 t6 t5b; do perl /tmp/conv.pl < $f.lean | sed 's/^\(.\)/  \1/' > c_$f.lean; done
